"""Source-specific expansions woven into independent V2 teaching scripts.
V1 files are read-only. No stock paragraph is inserted across multiple slides.
"""
from pathlib import Path
import json,re,hashlib
ROOT=Path(__file__).resolve().parents[1]
ORIGINAL=json.loads((ROOT/'teaching-notes.json').read_text())
EXTRA={};OVERRIDE={}
def expand(key,rows):
 for line in rows.strip().splitlines():
  page,body=line.split('|',1);parts=body.split(' || ');assert len(parts)==3,(key,page)
  EXTRA[f'{key}-{int(page):02}']=parts

def rewrite(key,page,*paragraphs):OVERRIDE[f'{key}-{page:02}']=list(paragraphs)

